/* Public files only. Generate one small page and two QR images per published
   location, sharing the existing event's identity, geometry and live room. */
const fs=require('node:fs'),path=require('node:path'),QR=require('qrcode');
const root=path.resolve(__dirname,'../..'),version='20261113d';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const json=value=>JSON.stringify(value).replace(/</g,'\\u003c');
const head=(title,url)=>`<!doctype html>
<!-- Generated by tools/special-events/make-stop-pages.cjs. -->
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escape(title)} · Austin.Chat</title><link rel="canonical" href="${url}">
<meta name="description" content="A free, local chat for Austin Studio Tour visitors. Open the map, visit the studio and chat with others in its marked zone.">
<link rel="icon" href="/favicon.ico?v=20261031f"><link rel="stylesheet" href="/style.css?v=20261029v"><link rel="stylesheet" href="/appearance.css?v=20261028h">
<link rel="stylesheet" href="/special-events/stop-page.css?v=${version}">
<script src="https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.118.0/dist/umd/supabase.min.js"></script>
<script src="/shared/visit.js?v=20261109g"></script><script src="/shared/session.js?v=20261031a"></script>
<script src="/shared/member.js?v=20261030c"></script><script src="/shared/preferences.js?v=20261104a"></script><script src="/shared/favorite-button.js?v=20261030c"></script>`;
const foot=`<script src="/shell.js?v=20261113a"></script></body></html>\n`;
const csv=value=>'"'+String(value??'').replace(/"/g,'""')+'"';
async function generate(){
  const registry=JSON.parse(fs.readFileSync(path.join(root,'special-events/registry.json'),'utf8'));
  const record=registry.find(e=>e.id==='austin-studio-tour-2026');
  if(!record)throw Error('Studio Tour registry entry is missing');
  const event=require('../../special-events/model.js').validate(JSON.parse(fs.readFileSync(path.join(root,record.data),'utf8')));
  const base=record.page+'stops/',out=new Map(),numbers=new Set(),rows=[];
  for(const feature of event.features){
    const p=feature.properties,n=String(p.number);
    if(!/^\d+$/.test(n)||numbers.has(n))throw Error('Duplicate or unsafe stop number');numbers.add(n);
    const url='https://austin.chat'+base+n+'/',title=`Stop ${n} · ${p.title}`;
    const one={id:event.id,title:event.title,dates:event.dates,bounds:event.bounds,expiresAt:record.expiresAt,
      features:[{type:'Feature',geometry:feature.geometry,properties:{id:p.id,number:p.number,title:p.title,chatBoundary:p.chatBoundary}}]};
    const note=p.chatBoundaryDetails?.sharedBuilding?'This building has separate zones for nearby stops. Your GPS must place you inside this stop’s shaded zone.':p.chatBoundaryDetails?.method==='pin-approximation'?'This stop uses an approximate chat zone around the studio.':'The shaded area is this studio’s chat zone. GPS accuracy can vary, especially indoors.';
    const html=head(title,url)+`
<link rel="stylesheet" href="https://unpkg.com/maplibre-gl@5/dist/maplibre-gl.css">
<script src="https://unpkg.com/maplibre-gl@5/dist/maplibre-gl.js"></script></head><body>
<main class="page-main"><article class="stop-page">
<nav class="stop-nav" aria-label="Tour navigation"><a href="${record.page}">Full tour map</a><a href="${base}">All studio chat pages</a></nav>
<header><p class="stop-kicker">Austin Studio Tour 2026 · Stop ${n}</p><h1>${escape(p.title)}</h1><p class="stop-address">${escape(p.address)}</p>
<p class="stop-dates">${escape(event.dateLabel)} · <a href="${escape(p.url)}" target="_blank" rel="noopener noreferrer">Official stop &amp; hours ↗</a></p></header>
<div id="stop-active"><div class="stop-map-stage"><div id="stop-map" role="region" aria-label="Map of stop ${n} and its chat zone"></div>
<div class="stop-map-actions"><button id="ctrlChat" type="button">Chat ↓</button><button id="stop-fit" type="button">Center map</button></div></div>
<p class="stop-map-note">${escape(note)}</p>
<section class="stop-chat" id="stop-chat" aria-labelledby="members-heading"><h2 id="members-heading">Chat at this studio</h2>
<p>Free to join. No account needed. Allow location, enter the shaded zone and turn on Visible to chat with other visitors here.</p>
<div class="stop-actions"><button id="stop-gps" class="stop-primary" type="button">Use my GPS</button><button id="visibleBtn" type="button" aria-pressed="false" disabled>Hidden</button><button id="chatBtn" type="button" disabled>Chat</button></div>
<p id="roomLine" role="status">Your location is used only when you choose Use my GPS.</p>
<p class="stop-identity">You: <span id="youHandle">Guest</span> <button id="newName" type="button" disabled>New name</button></p>
<h3>Visible visitors</h3><p id="peopleLine" role="status">Use GPS and turn on Visible to see who is here.</p><ul id="stop-members" aria-label="Visible visitors"></ul>
<div id="placeList" hidden></div>
<section id="chatwin" class="stop-conversation" hidden aria-label="Studio conversation"><header><strong id="chatRoom"></strong><button id="chatClose" type="button" aria-label="Close conversation">×</button></header><div id="chatPeople"></div>
<ul id="chatLines" aria-live="polite" aria-label="Messages"></ul><div class="stop-compose"><input id="chatText" type="text" autocomplete="off" aria-label="Message"><button id="chatSend" type="button">Send</button></div></section>
<p class="stop-note">Chat starts when another visible visitor is here. Messages are live only and disappear when you leave. Studio hosts also need to be inside this zone with this page open and Visible on.</p>
</section>
<details class="stop-share"><summary>Share this studio’s chat</summary><p>Send this link or QR code to someone visiting this stop.</p><div class="stop-actions"><button id="stop-copy" type="button">Copy link</button><a href="qr.png" download="austin-studio-stop-${n}.png">Download QR (PNG)</a><a href="qr.svg" download="austin-studio-stop-${n}.svg">Print QR (SVG)</a></div>
<img src="qr.svg" width="200" height="200" alt="QR code for Austin Studio Tour stop ${n}" loading="lazy"><p><a class="stop-permalink" href="${url}">${url}</a></p><p id="stop-share-status" role="status"></p></details>
<p class="stop-note">This temporary chat page closes November 24, 2026 at 10 PM Central. Explore more local conversations at <a href="/">Austin.Chat</a>.</p></div>
<section id="stop-expired" hidden><h2>This Studio Tour has ended</h2><p>The temporary studio chat is now closed.</p><a href="/">Explore Austin.Chat</a></section>
<noscript><p>Enable JavaScript to use the map and live chat.</p></noscript></article></main>
<script id="stop-data" type="application/json">${json(one)}</script>
<script src="/chat/copy.js?v=20261028i"></script><script src="/chat/config.js?v=20261029a"></script><script src="/chat/auth.js?v=20261030c"></script>
<script src="/chat/locate.js?v=20261108b"></script><script src="/chat/chat.js?v=20261109a"></script><script src="/chat/panel.js?v=20261109a"></script><script src="/chat/room.js?v=20261112a"></script>
<script src="/special-events/model.js?v=20261109c"></script><script src="/special-events/stop-page.js?v=${version}"></script>
`+foot;
    const dir=(base+n+'/').slice(1);out.set(dir+'index.html',Buffer.from(html));
    const options={errorCorrectionLevel:'M',margin:4,scale:8};
    out.set(dir+'qr.svg',Buffer.from(await QR.toString(url,{...options,type:'svg'})));
    out.set(dir+'qr.png',await QR.toBuffer(url,{...options,type:'png'}));
    rows.push({number:p.number,title:p.title,address:p.address,url,qr:url+'qr.png',svg:url+'qr.svg',official:p.url});
  }
  rows.sort((a,b)=>a.number-b.number);
  out.set(base.slice(1)+'links.csv',Buffer.from('\ufeff'+[['Stop','Studio','Address','Chat URL','QR PNG','QR SVG','Official stop'],...rows.map(r=>[r.number,r.title,r.address,r.url,r.qr,r.svg,r.official])].map(row=>row.map(csv).join(',')).join('\r\n')+'\r\n'));
  out.set(base.slice(1)+'index.html',Buffer.from(head('Studio chat pages','https://austin.chat'+base)+`</head><body><main class="page-main"><article class="stop-page stop-directory">
<nav class="stop-nav"><a href="${record.page}">Full tour map</a></nav><p class="stop-kicker">Austin Studio Tour 2026</p><h1>A chat page for every studio stop</h1>
<p>Find a studio’s map, local chat and QR code. Share a link before visiting; chat with others when you’re inside its zone.</p>
<div id="stop-active"><p><a href="links.csv" download>Download all ${rows.length} links &amp; QR addresses (CSV)</a></p>
<label class="stop-search">Find a stop<input id="stop-search" type="search" placeholder="Studio, stop number or address" autocomplete="off"></label><p id="stop-count" role="status">${rows.length} studio stops</p>
<ul id="stop-directory">${rows.map(r=>`<li><div><a href="${r.number}/"><strong>Stop ${r.number} · ${escape(r.title)}</strong></a><p>${escape(r.address)}</p></div><a class="stop-qr-link" href="${r.number}/qr.png" download="austin-studio-stop-${r.number}.png" aria-label="Download QR for stop ${r.number}">QR ↓</a></li>`).join('\n')}</ul></div>
<section id="stop-expired" hidden><h2>This Studio Tour has ended</h2><p>These temporary studio chats are now closed.</p><a href="/">Explore Austin.Chat</a></section></article></main>
<script id="stop-data" type="application/json">${json({expiresAt:record.expiresAt})}</script><script src="/special-events/stop-page.js?v=${version}"></script>`+foot));
  return {files:out,rows};
}
async function main(){
  const {files,rows}=await generate(),check=process.argv.includes('--check');let bytes=0;
  const normalized=(name,data)=>name.endsWith('.png')?data:Buffer.from(data.toString('utf8').replace(/\r\n/g,'\n'));
  for(const [name,data]of files){const file=path.join(root,name);bytes+=data.length;if(check){if(!fs.existsSync(file)||!normalized(name,data).equals(normalized(name,fs.readFileSync(file))))throw Error('Generated file differs: '+name);}else{fs.mkdirSync(path.dirname(file),{recursive:true});fs.writeFileSync(file,data);}}
  const actual=fs.readdirSync(path.join(root,'maps/austin-studio-tour/stops'),{withFileTypes:true}).filter(d=>d.isDirectory()).map(d=>Number(d.name));
  if(actual.length!==rows.length||actual.some(n=>!rows.some(r=>r.number===n)))throw Error('Unexpected stop folder: review stale output before publishing');
  console.log(`${check?'Checked':'Generated'} ${rows.length} studio pages, ${files.size} files, ${(bytes/1024/1024).toFixed(2)} MiB.`);
}
module.exports={generate};if(require.main===module)main().catch(e=>{console.error(e.message);process.exitCode=1;});
